    "content": "name: Release\n\n# Runs when a maintainer pushes a version tag (vX.Y.Z) on the merge commit of a release pull request. See\n# \"Releases\" in CONTRIBUTING.md. The job checks the tag, creates a draft GitHub Release with the notes from\n# the pull request, and moves the major tag (vN). A maintainer reviews and publishes the draft.\non:\n  push:\n    tags: ['v[0-9]+.[0-9]+.[0-9]+']\n\npermissions:\n  contents: write # push the major tag, create the release\n  pull-requests: read # read the release notes from the pull request\n\nconcurrency:\n  group: release\n  cancel-in-progress: false\n\njobs:\n  release:\n    runs-on: ubuntu-latest\n    env:\n      TAG: ${{ github.ref_name }}\n      GH_TOKEN: ${{ github.token }}\n    steps:\n      - uses: actions/checkout@v6\n        with:\n          fetch-depth: 0 # main and all tags\n\n      - name: Check the tag\n        run: |\n          version=\"$(jq -r .version package.json)\"\n          if [ \"$TAG\" != \"v$version\" ]; then\n            echo \"::error::Tag $TAG does not agree with version $version in package.json\"\n            exit 1\n          fi\n          if [ \"$(jq -r .version package-lock.json)\" != \"$version\" ]; then\n            echo \"::error::package-lock.json does not have version $version. Use npm version $version --no-git-tag-version\"\n            exit 1\n          fi\n          if ! git merge-base --is-ancestor \"$GITHUB_SHA\" origin/main; then\n            echo \"::error::Tag $TAG is not on main. Tag the merge commit of the release pull request\"\n            exit 1\n          fi\n\n      - name: Setup Node.js\n        uses: actions/setup-node@v6\n        with:\n          node-version: '24'\n          cache: 'npm'\n\n      - name: Install dependencies\n        run: npm ci\n\n      - name: Run quality checks\n        run: npm run check\n\n      - name: Create the draft release\n        run: |\n          # The \"## Release notes\" section of the pull request that merged this commit, up to the next \"## \".\n          gh api \"repos/$GITHUB_REPOSITORY/commits/$GITHUB_SHA/pulls\" --jq '.[0].body // \"\"' \\\n            | tr -d '\\r' \\\n            | awk '/^## Release notes[[:space:]]*$/ { found = 1; next } found && /^## / { exit } found' \\\n            > notes.md\n          if ! grep -q '[^[:space:]]' notes.md; then\n            echo \"::error::The pull request of $GITHUB_SHA has no \\\"## Release notes\\\" section\"\n            exit 1\n          fi\n          previous=\"$(git describe --tags --abbrev=0 --match 'v[0-9]*.[0-9]*.[0-9]*' \"$GITHUB_SHA^\" 2>/dev/null || true)\"\n          if [ -n \"$previous\" ]; then\n            printf '\\n**Full Changelog**: %s/%s/compare/%s...%s\\n' \\\n              \"$GITHUB_SERVER_URL\" \"$GITHUB_REPOSITORY\" \"$previous\" \"$TAG\" >> notes.md\n          fi\n          gh release create \"$TAG\" --draft --verify-tag --title \"$TAG\" --notes-file notes.md\n          echo \"::notice::Review and publish the draft: $(gh release view \"$TAG\" --json url --jq .url)\"\n\n      - name: Move the major tag\n        run: |\n          major=\"${TAG%%.*}\"\n          latest=\"$(git tag --list \"$major.*.*\" --sort=-v:refname | head -n 1)\"\n          if [ \"$latest\" != \"$TAG\" ]; then\n            echo \"::notice::$latest is later than $TAG, so $major stays where it is\"\n            exit 0\n          fi\n          git config user.name 'github-actions[bot]'\n          git config user.email '41898282+github-actions[bot]@users.noreply.github.com'\n          git tag --force --annotate \"$major\" --message \"$major\" \"$GITHUB_SHA\"\n          git push --force origin \"refs/tags/$major\"\n",
    "revision": "UHSkYm3T2fVJ",
    "lines": 88
  },
